//! Fork: `reason` and `retryable` of every provider business code, against Node's tables
//! (`tests/fixtures/node-provider-codes.json`, generated by Node's `classifyModelFailure`). The fixture is checked in
//! both directions: every fixture row is a Rust table code, and every Rust table code has a fixture row.

use std::collections::BTreeSet;
use std::time::SystemTime;

use rust_cli_kernel_api::model::ProviderFailure;
use rust_cli_kernel_api::provider::WireProtocol;
use rust_cli_net::ResponseHeaders;
use serde_json::{Value, json};

use crate::errors::{Vendor, Verdict};

const FIXTURE: &str = include_str!("../../tests/fixtures/node-provider-codes.json");

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("the Node fixture is JSON")
}

fn rows() -> Vec<Value> {
    fixture()["rows"].as_array().expect("rows").clone()
}

fn provider_of(verdict: &Verdict) -> ProviderFailure {
    verdict
        .error
        .provider()
        .cloned()
        .unwrap_or_else(|| panic!("no provider code on {:?}", verdict.error))
}

fn zhipu_response(code: &str, status: u16) -> Verdict {
    let body = json!({"error": {"code": code, "message": "x"}}).to_string();
    crate::errors::classify_response(
        Vendor::Zhipu,
        WireProtocol::AnthropicMessages,
        (status, &ResponseHeaders::default()),
        &body,
        SystemTime::UNIX_EPOCH,
    )
}

fn zhipu_stream(code: &str) -> Verdict {
    let value = json!({"error": {"code": code, "message": "x"}});
    crate::errors::classify_stream_error(
        Vendor::Zhipu,
        WireProtocol::AnthropicMessages,
        &value,
        &value.to_string(),
    )
}

fn plan_response(code: &str, status: u16) -> Verdict {
    let body = json!({"error": {"type": "invalid_request_error", "code": code, "message": "x"}});
    crate::errors::classify_response(
        Vendor::Generic,
        WireProtocol::OpenAiResponses,
        (status, &ResponseHeaders::default()),
        &body.to_string(),
        SystemTime::UNIX_EPOCH,
    )
}

fn is_plan_code(code: &str) -> bool {
    code.starts_with("subscription_sharing_") || code.starts_with("chatpass_v2_")
}

fn verdict_for(code: &str, status: Option<u16>) -> Verdict {
    match (is_plan_code(code), status) {
        (true, Some(status)) => plan_response(code, status),
        (true, None) => {
            // A plan code in a stream: the same table, with no status.
            let value = json!({"type": "error", "error": {"type": "invalid_request_error", "code": code, "message": "x"}});
            crate::errors::classify_stream_error(
                Vendor::Generic,
                WireProtocol::OpenAiResponses,
                &value,
                &value.to_string(),
            )
        }
        (false, Some(status)) => zhipu_response(code, status),
        (false, None) => zhipu_stream(code),
    }
}

#[test]
fn every_table_code_has_nodes_reason_and_retryable_with_a_429() {
    let rows = rows();
    assert_eq!(rows.len(), 51, "42 zhipu codes and 9 plan codes");
    for row in rows {
        let code = row["code"].as_str().expect("code");
        let provider = provider_of(&verdict_for(code, Some(429)));
        assert_eq!(provider.code, code);
        assert_eq!(provider.status, Some(429), "{code}");
        assert_eq!(
            provider.reason,
            row["reason"].as_str().expect("reason"),
            "reason of {code} at 429"
        );
        assert_eq!(
            provider.retryable,
            row["retryable"].as_bool().expect("retryable"),
            "retryable of {code} at 429"
        );
    }
}

#[test]
fn every_table_code_has_nodes_reason_and_retryable_without_a_status() {
    for row in rows() {
        let code = row["code"].as_str().expect("code");
        let provider = provider_of(&verdict_for(code, None));
        assert_eq!(provider.status, None, "{code}");
        assert_eq!(
            provider.reason,
            row["reasonWithoutStatus"].as_str().expect("reason"),
            "reason of {code} without a status"
        );
        assert_eq!(
            provider.retryable,
            row["retryableWithoutStatus"].as_bool().expect("retryable"),
            "retryable of {code} without a status"
        );
    }
}

/// Node classifies the five unmapped zhipu codes by HTTP status (`classifyProviderBusinessFailure`): 401/403 are
/// `auth_failed`, 400/404/422 `invalid_request`, 429 `rate_limited`, 5xx `server_error` (retryable), others `unknown`.
#[test]
fn the_unmapped_codes_follow_nodes_status_ladder() {
    let rows = fixture()["fallbackByStatus"]
        .as_array()
        .expect("fallbackByStatus")
        .clone();
    assert_eq!(rows.len(), 45, "5 codes at 9 statuses");
    for row in rows {
        let code = row["code"].as_str().expect("code");
        let verdict = match row["status"].as_u64() {
            Some(status) => zhipu_response(code, u16::try_from(status).expect("status")),
            None => zhipu_stream(code),
        };
        let provider = provider_of(&verdict);
        let at = format!("{code} at {:?}", row["status"]);
        assert_eq!(
            provider.reason,
            row["reason"].as_str().expect("reason"),
            "{at}"
        );
        assert_eq!(
            provider.retryable,
            row["retryable"].as_bool().expect("retryable"),
            "{at}"
        );
    }
}

/// The fixture and the Rust tables agree in both directions: a code added to either side without the other fails.
#[test]
fn the_rust_tables_and_the_fixture_name_the_same_codes() {
    let fixture_codes: BTreeSet<String> = rows()
        .iter()
        .map(|row| row["code"].as_str().expect("code").to_owned())
        .collect();
    let mut rust_codes: BTreeSet<String> = super::zhipu::CODES
        .iter()
        .map(|(code, _, _)| (*code).to_owned())
        .collect();
    rust_codes.extend(super::siwc::CODES.iter().map(|code| (*code).to_owned()));
    assert_eq!(rust_codes, fixture_codes);
}

/// A code the table does not know still names the provider on a response, as it does on a stream (Node attaches
/// every provider code it reads). The protocol's own class is kept; the terms follow the status ladder.
#[test]
fn an_unmapped_code_on_a_response_keeps_its_provider_code() {
    let body = json!({"error": {"code": "9999", "message": "x"}}).to_string();
    let at = |status: u16| {
        crate::errors::classify_response(
            Vendor::Zhipu,
            WireProtocol::AnthropicMessages,
            (status, &ResponseHeaders::default()),
            &body,
            SystemTime::UNIX_EPOCH,
        )
    };
    let limited = at(429);
    let provider = provider_of(&limited);
    assert_eq!(provider.code, "9999");
    assert_eq!(provider.status, Some(429));
    assert_eq!(provider.reason, "rate_limited");
    assert!(provider.retryable);
    let unavailable = provider_of(&at(503));
    assert_eq!(unavailable.reason, "server_error");
    assert!(unavailable.retryable);
    assert_eq!(
        limited.class,
        crate::errors::Class::RateLimited,
        "the protocol keeps its class"
    );
}
